const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
$('#toast').setAttribute('role','status');$('#toast').setAttribute('aria-live','polite');
const db={norte:[['Torre Norte',['Instalaciones eléctricas','Prevención'],['Protección colectiva','Pedido de cable','Checklist Planta 2'],false],['Anexo Norte',['Logística','Prevención'],['Recepción de material','Plano de acceso','Checklist almacén'],true]],atlas:[['Centro Logístico Sur',['Logística','Prevención'],['Entrega muelle 3','Plano de rampa','Checklist recepción'],false],['Terminal Puerto',['Operaciones','Prevención'],['Señalización de muelle','Plano de acceso','Checklist turno'],true]]};let offline=false,selected='';
function toast(x){$('#toast').textContent=x;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200)}function go(v){$$('.view').forEach(x=>x.classList.toggle('active',x.id===v));$$('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===v))}function work(){let co=$('#company').value,all=db[co],project=$('#project');project.innerHTML=all.map((x,i)=>`<option value="${i}">${x[0]}</option>`).join('');show()}function show(){let co=$('#company').value,o=db[co][+$('#project').value||0],d=$('#department');d.innerHTML=o[1].map(x=>`<option>${x}</option>`).join('');let company=co==='norte'?'Norte Construcción':'Atlas Servicios',j=o[2];$('#scopeNote').textContent=`Datos simulados: ${company} · ${o[0]} · ${d.value}.`;$('#attention').innerHTML=j.map((x,i)=>`<article class="attention-item" style="--tone:var(--${i?'amber':'risk'})"><div><h2>${x}</h2><p>Excepción del alcance simulado.</p></div><span>Responsable<b>${i?'Equipo local':'Responsable de obra'}</b></span><span>Vencimiento<b>${i?'Mañana · 10:00':'Hoy · 12:30'}</b></span><span>Evidencia<b>${i+1} registros</b></span><button class="button" data-view="${i===2?'checklists':i===1?'plans':'incidents'}">Abrir</button></article>`).join('');$('#workInbox').innerHTML=j.map((x,i)=>`<article class="panel"><h2>${x}</h2><p>${i===2?'Checklist':'Trabajo'} · ${o[0]} · ${i+1} evidencias simuladas</p></article>`).join('');$('#rows').innerHTML=o[3]?'<tr><td colspan="5">No hay incidencias para este alcance simulado.</td></tr>':`<tr><td>Crítica</td><td>${j[0]}</td><td>Responsable de obra</td><td>Hoy · 12:30</td><td>1</td></tr>`;$('#detail').textContent=o[3]?'Sin incidencia seleccionada en este alcance.':`${j[0]} · evidencia simulada`;$('#panoramaText').textContent=`Resumen simulado de ${o[0]}.`;$('#panoramaMetrics').textContent=o[3]?'Sin indicadores pendientes para este alcance.':'Avance 72% · 1 excepción abierta.';$('#checklistText').textContent=j[2];$('#calendarItems').innerHTML=`<article><h2>${j[0]}</h2><p>Responsable local · Hoy · evidencia simulada</p></article>`;$('#chatTitle').textContent=j[0];$('#chatText').textContent=`Respuesta contextual limitada a ${o[0]}.`;$('#memoryText').textContent=o[3]?'No hay memoria confirmada para este alcance simulado.':`Memoria procedente de ${o[0]} · confianza simulada.`;$('#nexoText').textContent=o[3]?'Sin resultados recuperados para este alcance.':`Resultados simulados vinculados a ${o[0]}.`;$('#planMarks').innerHTML=j.slice(0,2).map((x,i)=>`<button class="tag ${i?'amber':'risk'}" style="${i?'top:55%;right:20%':'top:25%;left:20%'}">${x}</button>`).join('');$$('[data-view]').forEach(x=>x.onclick=()=>go(x.dataset.view))}function sync(){let s=$('#syncStatus'),icon=$('#syncIcon'),text=$('#syncText');s.className='sync '+(offline?'offline':'');icon.textContent=offline?'⌁':'✓';text.textContent=offline?'Offline simulado · última información local':'Sincronizado';s.setAttribute('aria-label',text.textContent);$('#offline').setAttribute('aria-label',offline?'Volver a sincronizado simulado':'Activar modo offline simulado')}
$('#company').onchange=work;$('#project').onchange=show;$('#department').onchange=show;$('#offline').onclick=()=>{offline=!offline;sync();toast(offline?'Modo offline simulado; no se usan datos reales.':'Sincronización simulada restablecida.')};$('#theme').onclick=()=>document.body.classList.toggle('light');$('#scan').onclick=()=>toast('Escanear es una simulación local; no usa cámara.');$('#snooze').onclick=()=>{ $('#snooze').textContent='Pospuesto 1 h';$('#snooze').disabled=true;toast('Recordatorio pospuesto (simulado).')};$$('[data-state]').forEach(x=>x.onclick=()=>{$('#state').hidden=false;$('#state').innerHTML=`<div class="panel">${x.dataset.state==='loading'?'Cargando datos simulados…':x.dataset.state==='empty'?'No hay datos para este alcance.':'Se conserva la última lectura simulada.'}</div>`});work();sync();
